using System;using System.IO;using System.Linq;using System.Globalization;using System.Text;using IdleIntelligence.Core;using UnityEngine;
namespace IdleIntelligence.Runtime {
 [Serializable]public sealed class WebTransfer {public string format;public int version,sourceVersion;public string original,normalized,payload;public string[] notes;}
 public static class UnityWebImport {
  static double Number(SaveJsonValidation.Value v)=>double.Parse(v.Text,CultureInfo.InvariantCulture);
  static ScientificNumber Scientific(SaveJsonValidation.Value v){if(v==null||v.Kind!="object")throw new FormatException("Missing exact web balance");var terms=v.Field("terms");return ScientificNumber.FromData(new NumberData{m=Number(v.Field("m")),e=(long)Number(v.Field("e")),terms=terms?.Kind=="array"?terms.Items.Select(x=>new NumberTerm{index=(long)Number(x.Items[0]),value=(int)Number(x.Items[1])}).ToArray():null});}
  static void Equal(ScientificNumber native,SaveJsonValidation.Value web){if(native.CompareTo(Scientific(web))!=0)throw new FormatException("Web/native exact balance mismatch");}
  public static GameState Validate(string json){SaveJsonValidation.Validate(json,typeof(WebTransfer),true);var t=JsonUtility.FromJson<WebTransfer>(json);if(t.format!="idle-intelligence-web-transfer"||t.version!=1||t.sourceVersion<1||t.sourceVersion>63||string.IsNullOrEmpty(t.original)||string.IsNullOrEmpty(t.normalized)||string.IsNullOrEmpty(t.payload))throw new FormatException("Unsupported web transfer");var original=SaveJsonValidation.Parse(t.original);if((int)Number(original.Field("version"))!=t.sourceVersion)throw new FormatException("Original version mismatch");var normalized=SaveJsonValidation.Parse(t.normalized);if(Number(normalized.Field("version"))!=63)throw new FormatException("Unsupported normalized web version");var d=new UnitySaveCodec().Decode(t.payload,0);var s=d.ToState();void Check(GameState n,SaveJsonValidation.Value w){var e=w.Field("exactEconomy");Equal(n.Credits,e.Field("credits"));Equal(n.Data,e.Field("data"));Equal(n.RunCredits,e.Field("runCreditsEarned"));Equal(n.LifetimeCreditsExact,e.Field("lifetimeCreditsEarned"));Equal(n.LifetimeEligibleExact,e.Field("lifetimeEligibleCredits"));Equal(n.LifetimeDataExact,e.Field("lifetimeDataGenerated"));Equal(n.Prestige.Total,e.Field("totalINTEarned"));Equal(n.Prestige.Free,e.Field("unspentINT"));Equal(n.Prestige.Cycle,e.Field("cycleINTEarned"));if(n.SavedAt!=Number(w.Field("savedAt"))||n.Retention.gems!=Number(w.Field("gems"))||n.Quality!=Number(w.Field("qualityLevel"))||n.Efficiency!=Number(w.Field("efficiencyLevel")))throw new FormatException("Web state mismatch");var hw=w.Field("hardwareCounts");for(int i=0;i<Balance.Hardware.Length;i++)if(n.Hardware[i]!=Number(hw.Field(Balance.Hardware[i].Id)))throw new FormatException("Web hardware mismatch");var items=w.Field("inventory").Items;if(items.Count!=n.Workshop.inventory.Length||items.Any(item=>!n.Workshop.inventory.Any(x=>x.id==item.Field("id").Text&&x.type==item.Field("type").Text&&x.level==Number(item.Field("level")))))throw new FormatException("Web inventory mismatch");}
   var web=normalized.Field("state");Check(s,web);if(t.sourceVersion==63)Check(s,original.Field("state"));if(ChallengeRules.Active(s))Check(s.Challenges.Main,web.Field("challengeSession").Field("main"));s.Web=new WebArchive{present=true,sourceVersion=t.sourceVersion,original=t.original,normalized=t.normalized,notes=t.notes??Array.Empty<string>()};if(ChallengeRules.Active(s))s.Challenges.Main.Web=s.Web.Copy();Game.Validate(s);return s;
  }
  public static GameState InspectFile(string path){if(new FileInfo(path).Length>16*1024*1024)throw new FormatException("Transfer exceeds 16 MiB");return Validate(new UTF8Encoding(false,true).GetString(File.ReadAllBytes(path)).TrimStart('\uFEFF'));}
 }
}
